-- ============================================================
--  Тема «Теперішні часи (Present Tenses)»: теорія у кроковому форматі + вправи
--  Згенеровано з mig/present_tenses.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.topics        add column if not exists subtopics jsonb not null default '[]'::jsonb;
alter table public.theory_blocks add column if not exists subtopic  text;
alter table public.exercises     add column if not exists subtopic  text;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
-- тип вправи «translate» (переклад і письмо) дозволено в exercises.type
alter table public.exercises drop constraint if exists exercises_type_check;
alter table public.exercises add constraint exercises_type_check
  check (type in ('order', 'choice', 'gap', 'cross', 'abcd', 'translate'));
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position, subtopics)
values ($g0$present_tenses$g0$, $g1$Теперішні часи (Present Tenses)$g1$, $g2$Present Simple, Present Continuous, Present Perfect і Present Perfect Continuous: форми, вживання, слова-маркери, типові помилки, порівняння часів. Є вправи на переклад речень з перевіркою й поясненням помилок.$g2$, 13, $g3$[{"slug":"pres_simple","title":"Present Simple: звички, факти, розклади","description":"Постійні й повторювані дії, загальні факти, розклади. Утворення з do/does і -s для he/she/it."},{"slug":"pres_cont","title":"Present Continuous: зараз і тимчасово","description":"Дія в момент мовлення, тимчасові й змінні ситуації, плани. Дієслова стану. Різниця від Present Simple."},{"slug":"pres_perf","title":"Present Perfect: результат і досвід","description":"Дія без точного часу, свіжий результат, досвід, кількість, for/since. Різниця від Past Simple."},{"slug":"pres_perf_cont","title":"Present Perfect Continuous: дія триває до тепер","description":"Дія почалась у минулому, триває певний час і ще не завершена, або щойно закінчилась із видимим результатом."},{"slug":"pres_mix","title":"Усі теперішні часи разом","description":"Порівняння чотирьох часів, вибір потрібного, змішані вправи й тести. Окремої теорії тут мало: усе — у попередніх підтемах.","mix":true}]$g3$::jsonb)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position, subtopics = excluded.subtopics;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g4$ps_form$g4$, $g5$Present Simple: як утворюється$g5$, $g6$elementary$g6$, $g7$formula$g7$, $g8${"step":"Present Simple: як утворюється","kicker":"Як утворюється","lead":"Present Simple — найпростіший час. У ствердженні це початкова форма дієслова, а для <b>he / she / it</b> додаємо <b>-s</b>. У запереченні й питанні з'являється допоміжне <b>do / does</b>, і тоді дієслово знову без -s.","tiles":[{"role":"підмет","label":"I / you / we / they","tone":"noun"},{"role":"дієслово","label":"work","tone":"colour"}],"legend":[{"tone":"noun","label":"he / she / it → work + s: He works."},{"tone":"colour","label":"заперечення й питання: do / does + дієслово без -s"}],"examples":[{"text":"I <b>work</b> in a bank.","plain":"I work in a bank.","note":"ствердження"},{"text":"She <b>works</b> in a bank.","plain":"She works in a bank.","note":"he / she / it + s"},{"text":"He <b>doesn't work</b> on Sundays.","plain":"He doesn't work on Sundays.","note":"заперечення"},{"text":"<b>Does</b> she <b>work</b> in a bank?","plain":"Does she work in a bank?","note":"питання"},{"text":"<b>Do</b> they <b>work</b> here? — Yes, they <b>do</b>.","plain":"Do they work here? Yes, they do.","note":"коротка відповідь"}],"note":"<b>To be</b> (am / is / are) допоміжного do не потребує: <i>She is not (isn't) at home. Are you ready?</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">work</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">don't (do not) work</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Do I / you / we / they work?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">he / she / it</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">work<b>s</b></td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">doesn't (does not) work</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Does he / she / it work?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">to be: I</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">am</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">am not</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Am I…?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">to be: he / she / it</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">is</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">isn't</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Is he…?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">to be: you / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">are</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">aren't</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Are you…?</td></tr></tbody>\n</table></div>"}]}$g8$::jsonb, null, 0, $g9$pres_simple$g9$
from public.topics where slug = $g10$present_tenses$g10$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
