insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g11$ps_use$g11$, $g12$Present Simple: коли вживаємо$g12$, $g13$elementary$g13$, $g14$cases$g14$, $g15${"kicker":"Коли вживаємо","lead":"Present Simple описує те, що «взагалі правда» або «завжди так буває», а не те, що відбувається просто зараз.","cards":[{"icon":"∞","title":"Постійні дії та стани","text":"Те, що не змінюється: професія, місце проживання, звички характеру.","example":"<b>He works</b> in the bank. She <b>lives</b> in Kyiv.","examplePlain":"He works in the bank. She lives in Kyiv."},{"icon":"↻","title":"Повторювані дії","text":"Що відбувається регулярно. Тут майже завжди є слова частоти.","example":"They <b>often go</b> out for supper. We <b>go</b> to the pool twice a week.","examplePlain":"They often go out for supper. We go to the pool twice a week."},{"icon":"◎","title":"Загальні факти й закони","text":"Істини, наукові факти, прислів'я.","example":"The sun <b>rises</b> in the east. Water <b>boils</b> at 100 °C.","examplePlain":"The sun rises in the east. Water boils at 100 °C."},{"icon":"⏱","title":"Розклади й програми","text":"Рейси, сеанси, уроки: навіть коли йдеться про майбутнє, бо це «за розкладом».","example":"The train <b>departs</b> at seven o'clock tomorrow.","examplePlain":"The train departs at seven o'clock tomorrow."},{"icon":"▶","title":"Коментарі, сюжети, інструкції","text":"Спортивні коментарі, переказ сюжету книжки чи фільму, покрокові інструкції.","example":"He <b>acts</b> brilliantly in this play. First you <b>open</b> the file.","examplePlain":"He acts brilliantly in this play. First you open the file."}]}$g15$::jsonb, null, 1, $g16$pres_simple$g16$
