insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g18$ps_markers$g18$, $g19$Present Simple: маркери й правопис$g19$, $g20$elementary$g20$, $g21$pairs$g21$, $g22${"step":"Present Simple: маркери й правопис","kicker":"Слова-маркери","lead":"Слова частоти підказують Present Simple. Вони стоять <b>перед основним дієсловом</b>, але <b>після to be</b>.","groups":[{"title":"Слова частоти","note":"від 100% до 0%","items":[["always","She always walks to work."],["usually","We usually have lunch at one."],["often","They often go out for supper."],["sometimes","He sometimes plays chess."],["seldom / rarely","I rarely watch TV."],["never","She never eats meat."]]},{"title":"Інші маркери","note":"зазвичай в кінці речення","items":[["every day / week","I check my mail every day."],["on Mondays","We have a test on Mondays."],["twice a week","He swims twice a week."],["in the morning","She jogs in the morning."],["from time to time","I visit them from time to time."]]},{"title":"Закінчення -s / -es (he, she, it)","note":"правопис","items":[["work → works","most verbs: + s"],["watch → watches","ch, sh, s, x, o: + es"],["go → goes","do → does"],["study → studies","приголосна + y → ies"],["play → plays","голосна + y → ys"],["have → has","виняток"]]}],"notes":["<b>Місце слова частоти:</b> <i>She <b>is always</b> late</i> (після to be), але <i>She <b>always</b> comes late</i> (перед дієсловом)."]}$g22$::jsonb, null, 2, $g23$pres_simple$g23$
