insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g25$ps_traps$g25$, $g26$Present Simple: типові помилки$g26$, $g27$intermediate$g27$, $g28$traps$g28$, $g29${"kicker":"Типові помилки","lead":"Найчастіше помиляються з -s, з допоміжним do / does і з вибором між Simple та Continuous.","items":[{"title":"Забули -s у he / she / it","bad":"He work in a bank.","good":"He <b>works</b> in a bank.","goodPlain":"He works in a bank.","rule":"Для he / she / it у ствердженні додаємо -s / -es."},{"title":"-s залишили після does","bad":"Does he works here?","good":"Does he <b>work</b> here?","goodPlain":"Does he work here?","rule":"Після do / does дієслово без -s: закінчення «забирає» допоміжне does."},{"title":"Заперечення без do / does","bad":"He not works. I no like tea.","good":"He <b>doesn't work</b>. I <b>don't like</b> tea.","goodPlain":"He doesn't work. I don't like tea.","rule":"Заперечення в Present Simple створює do / does + not, а не просто not чи no."},{"title":"Simple замість Continuous для «зараз»","bad":"Look! He plays football.","good":"Look! He <b>is playing</b> football.","goodPlain":"Look! He is playing football.","rule":"Те, що відбувається просто зараз, — Continuous. Simple — для звичок і фактів."},{"title":"Слово частоти не на своєму місці","bad":"She goes always to the gym.","good":"She <b>always goes</b> to the gym.","goodPlain":"She always goes to the gym.","rule":"Always, often, usually стоять перед основним дієсловом (але після am / is / are)."}]}$g29$::jsonb, null, 3, $g30$pres_simple$g30$
