insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g32$pc_form$g32$, $g33$Present Continuous: як утворюється$g33$, $g34$elementary$g34$, $g35$formula$g35$, $g36${"step":"Present Continuous: як утворюється","kicker":"Як утворюється","lead":"Present Continuous = <b>am / is / are</b> + дієслово з <b>-ing</b>. Допоміжне дієслово змінюється за підметом, а -ing лишається завжди.","tiles":[{"role":"підмет","label":"I / he / we…","tone":"noun"},{"role":"am / is / are","label":"is","tone":"colour"},{"role":"V-ing","label":"working","tone":"origin"}],"legend":[{"tone":"noun","label":"I → am, he / she / it → is, you / we / they → are"},{"tone":"origin","label":"V + ing: work → working, make → making, run → running"}],"examples":[{"text":"We <b>are listening</b> to music now.","plain":"We are listening to music now.","note":"ствердження"},{"text":"He <b>isn't working</b> today.","plain":"He isn't working today.","note":"заперечення"},{"text":"<b>Are</b> you <b>flying</b> to Paris next week?","plain":"Are you flying to Paris next week?","note":"питання"},{"text":"What <b>is</b> she <b>doing</b>? — She <b>is cooking</b>.","plain":"What is she doing? She is cooking.","note":"спеціальне питання"}],"note":"Скорочення: <i>I'm, he's, we're, isn't, aren't</i>. Питання: допоміжне виходить на перше місце — <i>Is he working?</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">am working (I'm working)</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">am not working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Am I working?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">he / she / it</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">is working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">isn't working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Is he working?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">you / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">are working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">aren't working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Are you working?</td></tr></tbody>\n</table></div>"}]}$g36$::jsonb, null, 4, $g37$pres_cont$g37$
