insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g39$pc_use$g39$, $g40$Present Continuous: коли вживаємо$g40$, $g41$elementary$g41$, $g42$cases$g42$, $g43${"kicker":"Коли вживаємо","lead":"Present Continuous показує дію «в процесі»: вона почалась, іще триває і зараз не завершена.","cards":[{"icon":"●","title":"Дія в момент мовлення","text":"Те, що відбувається просто зараз, коли ми говоримо.","example":"We <b>are listening</b> to music now. Look! It <b>is snowing</b>.","examplePlain":"We are listening to music now. Look! It is snowing."},{"icon":"⌛","title":"Тимчасова ситуація","text":"Не зараз саме, але «в цей період»: ці дні, цього місяця.","example":"He <b>is working</b> hard these days.","examplePlain":"He is working hard these days."},{"icon":"↗","title":"Ситуація, що змінюється","text":"Особливо з дієсловами become, get, grow, increase, change.","example":"It <b>is getting</b> colder. Prices <b>are rising</b>.","examplePlain":"It is getting colder. Prices are rising."},{"icon":"📅","title":"Плани на найближче майбутнє","text":"Домовленість, яка точно відбудеться: є час, місце, квитки.","example":"You <b>are flying</b> to Paris next week.","examplePlain":"You are flying to Paris next week."},{"icon":"😠","title":"Роздратування з always","text":"Always + Continuous = дратує, що так постійно трапляється.","example":"He <b>is always boasting</b>! You <b>are always losing</b> your keys!","examplePlain":"He is always boasting! You are always losing your keys!"}]}$g43$::jsonb, null, 5, $g44$pres_cont$g44$
