insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g46$pc_markers$g46$, $g47$Present Continuous: маркери й правопис -ing$g47$, $g48$elementary$g48$, $g49$pairs$g49$, $g50${"step":"Present Continuous: маркери й правопис -ing","kicker":"Слова-маркери","lead":"Маркери «зараз» і «цього періоду» вказують на Continuous. Закінчення -ing пишемо за простими правилами.","groups":[{"title":"Маркери часу","note":"зазвичай на початку або в кінці","items":[["now","We are listening to music now."],["at the moment","She is busy at the moment."],["today / tonight","I am staying at home tonight."],["at present","They are living in Rome at present."],["these days","He is working hard these days."],["Look! Listen!","Look! It is raining."]]},{"title":"Правопис -ing","note":"як змінюється дієслово","items":[["work → working","просто + ing"],["make → making","-e зникає"],["run → running","одна голосна + одна приголосна: подвоюємо"],["stop → stopping","подвоюємо останню приголосну"],["lie → lying","ie → y"],["play → playing","y лишається"]]}]}$g50$::jsonb, null, 6, $g51$pres_cont$g51$
