insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g53$pc_stative$g53$, $g54$Дієслова стану: Simple, а не Continuous$g54$, $g55$elementary$g55$, $g56$pairs$g56$, $g57${"step":"Дієслова стану: Simple, а не Continuous","kicker":"Винятки","lead":"Дієслова, що описують <b>стан, думку, почуття, володіння</b>, зазвичай не вживаються в Continuous: <i>know, understand, want, like, love, hate, need, believe, belong, own, seem, remember</i>. Але деякі мають інше значення, коли означають <b>дію</b>, і тоді Continuous можливий.","groups":[{"title":"have","note":"стан ↔ дія","items":[["has a cottage (володіння)","My aunt has a cottage."],["is having lunch (їсть)","The secretary is having lunch now."],["is having a lesson","Chris is having a driving lesson."]]},{"title":"think","note":"думка ↔ процес","items":[["think = вважати","I think it's a great idea."],["am thinking = обдумую","I'm thinking about the cinema tonight."]]},{"title":"see / taste / smell / feel / look","note":"відчуття ↔ дія","items":[["see = бачити; is seeing = зустрічається","Albert is seeing his dentist at 3."],["tastes bitter; is tasting = куштує","Why are you tasting the salad?"],["smells sour; is smelling = нюхає","Why are you smelling the milk?"],["looks funny (виглядає); is looking = дивиться","Nora is looking through the documents."]]},{"title":"be / enjoy / come / weigh","note":"характер ↔ поведінка","items":[["is lazy (за характером); is being lazy (зараз поводиться)","Jessica is being lazy these days."],["enjoys (взагалі); are enjoying (зараз)","Are you enjoying this performance?"],["comes from (звідки родом); is coming from (їде)","She is coming from Warsaw now."],["weighs 6 kg (важить); is weighing (зважує)","The officer is weighing the suitcase."]]}],"notes":["<b>Перевірка:</b> якщо можна уявити, що хтось це «робить» як дію, Continuous можливий. Якщо це стан чи думка (<i>I know, he wants, it costs</i>), — тільки Simple."]}$g57$::jsonb, null, 7, $g58$pres_cont$g58$
