insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g60$pc_traps$g60$, $g61$Present Continuous: типові помилки$g61$, $g62$intermediate$g62$, $g63$traps$g63$, $g64${"kicker":"Типові помилки","lead":"Українське «я працюю зараз» легко перенести в Simple, а дієслова стану — у Continuous. Обидві помилки виправляються правилом.","items":[{"title":"Дієслова стану в Continuous","bad":"I am knowing him. She is wanting a new dress.","good":"I <b>know</b> him. She <b>wants</b> a new dress.","goodPlain":"I know him. She wants a new dress.","rule":"Know, want, like, need, understand — стан: тільки Simple."},{"title":"Забули am / is / are","bad":"She watching TV now.","good":"She <b>is watching</b> TV now.","goodPlain":"She is watching TV now.","rule":"Continuous = допоміжне be + -ing; одне -ing без be не працює."},{"title":"Simple для плану чи «зараз»","bad":"Henry picks me up at eight tomorrow.","good":"Henry <b>is picking</b> me up at eight tomorrow.","goodPlain":"Henry is picking me up at eight tomorrow.","rule":"Особистий домовлений план — Continuous. Simple — лише для розкладів (The train leaves at eight)."},{"title":"Continuous для розкладу","bad":"The bus is arriving at 8.","good":"The bus <b>arrives</b> at 8.","goodPlain":"The bus arrives at 8.","rule":"Розклад, програма, графік — Present Simple."},{"title":"Не додали -ing / не подвоїли","bad":"He is runing. They are makeing tea.","good":"He is <b>running</b>. They are <b>making</b> tea.","goodPlain":"He is running. They are making tea.","rule":"run → running, make → making: перевіряйте правопис -ing."}]}$g64$::jsonb, null, 8, $g65$pres_cont$g65$
from public.topics where slug = $g66$present_tenses$g66$
