insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g67$pp_form$g67$, $g68$Present Perfect: як утворюється$g68$, $g69$elementary$g69$, $g70$formula$g70$, $g71${"step":"Present Perfect: як утворюється","kicker":"Як утворюється","lead":"Present Perfect = <b>have / has</b> + <b>третя форма</b> дієслова (V3). Для правильних дієслів V3 має закінчення -ed, неправильні треба вчити: <i>go – went – gone</i>.","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"have / has","label":"has","tone":"colour"},{"role":"V3","label":"worked / gone","tone":"origin"}],"legend":[{"tone":"noun","label":"he / she / it → has; I / you / we / they → have"},{"tone":"origin","label":"правильні: V + ed; неправильні: третя колонка таблиці"}],"examples":[{"text":"She <b>has just left</b> the office.","plain":"She has just left the office.","note":"ствердження"},{"text":"I <b>haven't seen</b> him since Monday.","plain":"I haven't seen him since Monday.","note":"заперечення"},{"text":"<b>Have</b> you <b>read</b> this article yet?","plain":"Have you read this article yet?","note":"питання"},{"text":"How long <b>has</b> he <b>worked</b> here? — For five years.","plain":"How long has he worked here? For five years.","note":"спеціальне питання"}],"note":"Скорочення: <i>I've, he's, they've, haven't, hasn't</i>. Але <i>he's</i> може бути й <i>he is</i>, тому дивіться, що стоїть далі: <i>he's gone</i> = has gone.","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">have worked</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">haven't worked</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Have you worked?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">he / she / it</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">has worked</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">hasn't worked</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Has he worked?</td></tr></tbody>\n</table></div>"}]}$g71$::jsonb, null, 9, $g72$pres_perf$g72$
from public.topics where slug = $g73$present_tenses$g73$
