  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g74$pp_use$g74$, $g75$Present Perfect: коли вживаємо$g75$, $g76$elementary$g76$, $g77$cases$g77$, $g78${"kicker":"Коли вживаємо","lead":"Present Perfect зв'язує минуле з теперішнім: нас цікавить не коли це сталося, а що з цього тепер.","cards":[{"icon":"?","title":"Дія в невизначений час","text":"Дія відбулась, але коли — не названо й неважливо.","example":"He <b>has repaired</b> his car.","examplePlain":"He has repaired his car."},{"icon":"✓","title":"Свіжий результат","text":"Дія закінчилась недавно, і її наслідок видно зараз (just, already).","example":"She <b>has just washed</b> the dishes: they're clean.","examplePlain":"She has just washed the dishes: they're clean."},{"icon":"★","title":"Особистий досвід і зміни","text":"Чи був, бачив, робив у житті (ever, never) і що змінилось.","example":"I <b>have never been</b> to Rome. Mary <b>has lost</b> weight.","examplePlain":"I have never been to Rome. Mary has lost weight."},{"icon":"№","title":"Кількість","text":"Скільки вже зроблено (how many, how much).","example":"He <b>has driven</b> eighty kilometres since morning.","examplePlain":"He has driven eighty kilometres since morning."},{"icon":"→","title":"Дія триває досі (for / since)","text":"Почалась у минулому й триває зараз, особливо зі станами (know, live, be).","example":"He <b>has worked</b> in our office for five years. (і працює досі)","examplePlain":"He has worked in our office for five years. (і працює досі)"}],"axis":{"title":"Present Perfect на часовій осі","points":[{"label":"колись","text":"дія відбулась"},{"label":"між тим і тепер","text":"час не названо"},{"label":"тепер","text":"результат / досвід / стан"}],"note":"Точний час минулого (yesterday, in 2019, two days ago) — вже не Present Perfect, а Past Simple."}}$g78$::jsonb, null, 10, $g79$pres_perf$g79$
from public.topics where slug = $g80$present_tenses$g80$
