insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g81$pp_markers$g81$, $g82$Present Perfect: слова-маркери$g82$, $g83$elementary$g83$, $g84$pairs$g84$, $g85${"step":"Present Perfect: слова-маркери","kicker":"Слова-маркери","lead":"Маркери Present Perfect вказують на «період до тепер» або на нечіткий час. Точні минулі маркери (yesterday, ago, last week) тут заборонені.","groups":[{"title":"Нечіткий час","note":"місце в реченні","items":[["just","She has just left. (перед V3)"],["already","We have already eaten. (перед V3 або в кінці)"],["yet","Have you finished yet? (питання, заперечення, в кінці)"],["ever","Have you ever been to Rome? (у питаннях)"],["never","I have never seen it. (заперечення вже є)"],["recently / lately","I haven't seen Bob lately."]]},{"title":"Період до тепер","note":"ще не закінчився","items":[["so far","I have made five calls so far."],["this week / month","I haven't called him this week."],["today","Have you seen Pam today?"],["since + момент","He has lived here since 2015."],["for + тривалість","She has been ill for three days."]]},{"title":"Типова пара: been / gone","note":"різні значення","items":[["has been to the market","був і повернувся"],["has gone to the market","пішов і ще там (або дорогою)"]]}],"notes":["<b>For або since?</b> <i>for</i> + тривалість (for ten years, for an hour); <i>since</i> + момент початку (since 2015, since Monday, since he left)."]}$g85$::jsonb, null, 11, $g86$pres_perf$g86$
from public.topics where slug = $g87$present_tenses$g87$
