  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g88$pp_vs_ps$g88$, $g89$Present Perfect чи Past Simple?$g89$, $g90$elementary$g90$, $g91$pairs$g91$, $g92${"step":"Present Perfect чи Past Simple?","kicker":"Порівняння","lead":"Обидва часи говорять про минуле. Past Simple — про минуле «закрите» (є час, і воно скінчилось). Present Perfect — про минуле, що пов'язане з теперішнім.","groups":[{"title":"Past Simple","note":"минуле саме по собі","items":[["точний час, який скінчився","He left the office an hour ago."],["стан у минулому","She lived in this house when she was seven."],["дії одна за одною","He put on his jacket, took an umbrella and left."],["when? / what time? / ago / yesterday / last…","When did she return? — At five."]]},{"title":"Present Perfect","note":"минуле + теперішнє","items":[["час не названо","He has just left the office."],["свіжий результат","She has just washed the dishes."],["дія триває досі (for / since)","He has worked here for five years."],["досвід, зміни, кількість; ever / never / yet / already","Have you ever played golf?"]]}],"notes":["<b>Тест:</b> якщо в реченні є <i>yesterday, ago, last week, in 2019, when…?</i>, — Past Simple. Якщо є <i>just, already, yet, ever, never, for, since, so far</i>, — Present Perfect."]}$g92$::jsonb, null, 12, $g93$pres_perf$g93$
