insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g95$pp_traps$g95$, $g96$Present Perfect: типові помилки$g96$, $g97$intermediate$g97$, $g98$traps$g98$, $g99${"kicker":"Типові помилки","lead":"Українське «я вже зробив» інколи підштовхує до Past Simple, а точний час тягне Present Perfect не в той бік.","items":[{"title":"Present Perfect з точним минулим часом","bad":"I have seen him yesterday.","good":"I <b>saw</b> him yesterday.","goodPlain":"I saw him yesterday.","rule":"Yesterday, ago, last week, in 2019, when…? — тільки Past Simple."},{"title":"Друга форма замість третьої","bad":"Have you spoke to him? She has went home.","good":"Have you <b>spoken</b> to him? She has <b>gone</b> home.","goodPlain":"Have you spoken to him? She has gone home.","rule":"Після have / has потрібна V3: speak – spoke – spoken, go – went – gone."},{"title":"has / have переплутали","bad":"She have just left. They has finished.","good":"She <b>has</b> just left. They <b>have</b> finished.","goodPlain":"She has just left. They have finished.","rule":"he / she / it → has; I / you / we / they → have."},{"title":"Since замість for (і навпаки)","bad":"We have waited for Monday. He has lived here since five years.","good":"We have waited <b>since</b> Monday. He has lived here <b>for</b> five years.","goodPlain":"We have waited since Monday. He has lived here for five years.","rule":"Since + момент початку, for + тривалість."},{"title":"Не той порядок слів у запитанні","bad":"Where has Jane and Emma been? Who have given you my number?","good":"Where <b>have</b> Jane and Emma been? Who <b>has</b> given you my number?","goodPlain":"Where have Jane and Emma been? Who has given you my number?","rule":"Допоміжне узгоджується з підметом; з who використовуємо has."}]}$g99$::jsonb, null, 13, $g100$pres_perf$g100$
