insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g102$ppc_form$g102$, $g103$Present Perfect Continuous: як утворюється$g103$, $g104$elementary$g104$, $g105$formula$g105$, $g106${"step":"Present Perfect Continuous: як утворюється","kicker":"Як утворюється","lead":"Present Perfect Continuous = <b>have / has been</b> + дієслово з <b>-ing</b>. Це Present Perfect (have / has + been) і Continuous (-ing) в одній формі.","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"have / has been","label":"has been","tone":"colour"},{"role":"V-ing","label":"working","tone":"origin"}],"legend":[{"tone":"noun","label":"he / she / it → has been; I / you / we / they → have been"},{"tone":"origin","label":"правопис -ing такий самий, як у Present Continuous"}],"examples":[{"text":"She <b>has been cooking</b> for two hours now.","plain":"She has been cooking for two hours now.","note":"ствердження"},{"text":"They <b>haven't been playing</b> since 10 o'clock.","plain":"They haven't been playing since ten o'clock.","note":"заперечення"},{"text":"How long <b>have</b> you <b>been waiting</b>?","plain":"How long have you been waiting?","note":"питання"},{"text":"Why <b>has</b> he <b>been</b> shouting?","plain":"Why has he been shouting?","note":"спеціальне питання"}],"note":"Скорочення: <i>I've been working, she's been working, haven't been, hasn't been</i>.","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">have been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">haven't been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Have you been working?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">he / she / it</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">has been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">hasn't been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Has he been working?</td></tr></tbody>\n</table></div>"}]}$g106$::jsonb, null, 14, $g107$pres_perf_cont$g107$
