insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g109$ppc_use$g109$, $g110$Present Perfect Continuous: коли вживаємо$g110$, $g111$elementary$g111$, $g112$cases$g112$, $g113${"kicker":"Коли вживаємо","lead":"Цей час відповідає на запитання «скільки це вже триває?» і «що ви робили, що так втомились?».","cards":[{"icon":"→","title":"Дія триває й досі","text":"Почалась у минулому, йде певний час і ще не закінчилась.","example":"We <b>have been watching</b> TV since 5 o'clock. (і досі дивимось)","examplePlain":"We have been watching TV since 5 o'clock. (і досі дивимось)"},{"icon":"💪","title":"Тривала дія з видимим результатом","text":"Дія щойно закінчилась, але було видно, що вона була довгою.","example":"Mike is out of breath. He <b>has been running</b>.","examplePlain":"Mike is out of breath. He has been running."},{"icon":"⏳","title":"Підкреслюємо тривалість","text":"Важливо, як довго: for, since, all day, how long.","example":"She <b>has been cooking</b> all day.","examplePlain":"She has been cooking all day."}]}$g113$::jsonb, null, 15, $g114$pres_perf_cont$g114$
