insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g116$ppc_markers$g116$, $g117$Present Perfect Continuous: маркери$g117$, $g118$elementary$g118$, $g119$pairs$g119$, $g120${"step":"Present Perfect Continuous: маркери","kicker":"Слова-маркери","lead":"З цим часом майже завжди називається тривалість або момент початку.","groups":[{"title":"Тривалість і початок","note":"типові слова","items":[["for two hours / a week","I have been waiting for two hours."],["since 5 o'clock / Monday / last year","He has been working since morning."],["all day / all morning","She has been cooking all day."],["how long…?","How long have you been learning English?"],["lately / recently","I have been feeling tired lately."]]}],"notes":["<b>Дієслова стану</b> (know, like, want, have = володіти) не вживаються в Continuous, тому: <i>I have known him for ten years</i>, а не have been knowing."]}$g120$::jsonb, null, 16, $g121$pres_perf_cont$g121$
