insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g123$ppc_vs_pp$g123$, $g124$Present Perfect чи Present Perfect Continuous?$g124$, $g125$elementary$g125$, $g126$pairs$g126$, $g127${"step":"Present Perfect чи Present Perfect Continuous?","kicker":"Порівняння","lead":"Обидва часи пов'язують минуле з теперішнім. Continuous дивиться на <b>процес і тривалість</b>, Perfect — на <b>результат і кількість</b>.","groups":[{"title":"Perfect Continuous: процес","note":"скільки триває","items":[["How long?","She has been reading for two hours."],["дія ще триває або щойно скінчилась","I'm tired: I have been working all day."],["немає кількості результату","He has been painting the house."]]},{"title":"Present Perfect: результат","note":"скільки зроблено","items":[["How many? / how much?","She has read three chapters."],["дія завершена, результат є","He has painted the house. (готово)"],["дієслова стану","I have known her for years."]]}],"notes":["<b>Порівняйте:</b> <i>She has been writing letters all morning</i> (процес) — <i>She has written ten letters</i> (кількість, результат)."]}$g127$::jsonb, null, 17, $g128$pres_perf_cont$g128$
from public.topics where slug = $g129$present_tenses$g129$
