insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g130$ppc_traps$g130$, $g131$Present Perfect Continuous: типові помилки$g131$, $g132$intermediate$g132$, $g133$traps$g133$, $g134${"kicker":"Типові помилки","lead":"Тут помиляються на трьох місцях: у структурі (have been + -ing), у since / for і в Present Continuous замість цього часу.","items":[{"title":"Present Continuous замість Perfect Continuous","bad":"We are waiting for two hours. She works here since April.","good":"We <b>have been waiting</b> for two hours. She <b>has been working</b> here since April.","goodPlain":"We have been waiting for two hours. She has been working here since April.","rule":"Тривалість (for / since) показує дію, що почалась раніше: потрібен Perfect Continuous (або Present Perfect для станів)."},{"title":"Забули been","bad":"Rob and Jack have swimming for an hour.","good":"Rob and Jack <b>have been swimming</b> for an hour.","goodPlain":"Rob and Jack have been swimming for an hour.","rule":"have / has + <b>been</b> + V-ing: been обов'язкове."},{"title":"Third person: has been","bad":"My cousin have been working here.","good":"My cousin <b>has been</b> working here.","goodPlain":"My cousin has been working here.","rule":"he / she / it → has been; I / you / we / they → have been."},{"title":"Порядок слів у запитанні","bad":"How long she has looked for a job? Who have been waiting?","good":"How long <b>has she been looking</b> for a job? Who <b>has been waiting</b>?","goodPlain":"How long has she been looking for a job? Who has been waiting?","rule":"Питальне слово + has/have + підмет + been + -ing; з who — has been."},{"title":"Дієслово стану в Perfect Continuous","bad":"I have been knowing him for years.","good":"I <b>have known</b> him for years.","goodPlain":"I have known him for years.","rule":"Know, like, want, be (стан) — Present Perfect Simple."}]}$g134$::jsonb, null, 18, $g135$pres_perf_cont$g135$
from public.topics where slug = $g136$present_tenses$g136$
on conflict (topic_id, block_key) do update set
