insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g137$mix_choose$g137$, $g138$Як вибрати теперішній час$g138$, $g139$elementary$g139$, $g140$cases$g140$, $g141${"kicker":"Порівняння чотирьох часів","lead":"Поставте собі три запитання: <b>регулярно чи зараз?</b> <b>є зв'язок із минулим?</b> <b>результат чи тривалість?</b> Відповіді підкажуть час.","cards":[{"icon":"1","title":"Present Simple","text":"Постійне, регулярне, факт, розклад. Слова: always, usually, every day.","example":"He <b>works</b> in a bank. The train <b>arrives</b> at five.","examplePlain":"He works in a bank. The train arrives at five."},{"icon":"2","title":"Present Continuous","text":"Те, що відбувається зараз, тимчасово, змінюється, домовлений план. Слова: now, at the moment, these days.","example":"He <b>is working</b> on a project these days.","examplePlain":"He is working on a project these days."},{"icon":"3","title":"Present Perfect","text":"Дія в невизначений час, свіжий результат, досвід, кількість, for / since зі станами. Слова: just, already, yet, ever, never.","example":"He <b>has repaired</b> his car. I <b>have never been</b> to Rome.","examplePlain":"He has repaired his car. I have never been to Rome."},{"icon":"4","title":"Present Perfect Continuous","text":"Дія почалась у минулому й триває, або щойно закінчилась з видимим результатом; важлива тривалість. Слова: for, since, all day, how long.","example":"We <b>have been watching</b> TV since five.","examplePlain":"We have been watching TV since five."}],"axis":{"title":"Те саме речення в чотирьох часах","points":[{"label":"Simple","text":"He reads a book (звичка)"},{"label":"Continuous","text":"He is reading a book (зараз)"},{"label":"Perfect","text":"He has read the book (завершено)"},{"label":"Perfect Cont.","text":"He has been reading it for an hour (триває)"}]}}$g141$::jsonb, null, 19, $g142$pres_mix$g142$
